#define REGMAP_FPGA_WAVEFORM_GEN_REG_5_SET_FEN(reg, val) \
    (((reg) & ~(((1U << 1) - 1) << 31)) | (((val) & ((1U << 1) - 1)) << 31))


/* EXT_INT_TRIG_REG Register Accessors */
/** @brief Get EIT field from EXT_INT_TRIG_REG register - Select trigger source. */
#define REGMAP_FPGA_EXT_INT_TRIG_REG_GET_EIT(reg) \
    (((reg) >> 0) & ((1U << 1) - 1))

/** @brief Set EIT field in EXT_INT_TRIG_REG register */
#define REGMAP_FPGA_EXT_INT_TRIG_REG_SET_EIT(reg, val) \
    (((reg) & ~(((1U << 1) - 1) << 0)) | (((val) & ((1U << 1) - 1)) << 0))

/** @brief Get MIM field from EXT_INT_TRIG_REG register - MCU interrupt source select (SPI mux must not be 00). */
#define REGMAP_FPGA_EXT_INT_TRIG_REG_GET_MIM(reg) \
    (((reg) >> 1) & ((1U << 2) - 1))

/** @brief Set MIM field in EXT_INT_TRIG_REG register */
#define REGMAP_FPGA_EXT_INT_TRIG_REG_SET_MIM(reg, val) \
    (((reg) & ~(((1U << 2) - 1) << 1)) | (((val) & ((1U << 2) - 1)) << 1))

/** @brief Get OTM field from EXT_INT_TRIG_REG register - Output trigger (trigger_o) source select. */
#define REGMAP_FPGA_EXT_INT_TRIG_REG_GET_OTM(reg) \
    (((reg) >> 3) & ((1U << 2) - 1))

/** @brief Set OTM field in EXT_INT_TRIG_REG register */
#define REGMAP_FPGA_EXT_INT_TRIG_REG_SET_OTM(reg, val) \
    (((reg) & ~(((1U << 2) - 1) << 3)) | (((val) & ((1U << 2) - 1)) << 3))

/** @brief Get STATUS_CONTROL field from EXT_INT_TRIG_REG register - Transport diagnostic controls in bits 31:23. The stream and acquisition-results settings clear the other diagnostic controls. */
#define REGMAP_FPGA_EXT_INT_TRIG_REG_GET_STATUS_CONTROL(reg) \
    (((reg) >> 23) & ((1U << 9) - 1))

/** @brief Set STATUS_CONTROL field in EXT_INT_TRIG_REG register */
#define REGMAP_FPGA_EXT_INT_TRIG_REG_SET_STATUS_CONTROL(reg, val) \
    (((reg) & ~(((1U << 9) - 1) << 23)) | (((val) & ((1U << 9) - 1)) << 23))


/* RESERVED_REG Register Accessors */
/** @brief Get RESERVED field from RESERVED_REG register */
#define REGMAP_FPGA_RESERVED_REG_GET_RESERVED(reg) \
    (((reg) >> 0) & (UINT32_MAX))

/** @brief Set RESERVED field in RESERVED_REG register */
#define REGMAP_FPGA_RESERVED_REG_SET_RESERVED(reg, val) \
    (((reg) & ~((UINT32_MAX) << 0)) | (((val) & (UINT32_MAX)) << 0))


/* TRANSPORT_STATUS Register Accessors */
/** @brief Get READY field from TRANSPORT_STATUS register - Stream data ready on the STREAM page, or acquisition results ready on the RESULTS page. */
#define REGMAP_FPGA_TRANSPORT_STATUS_GET_READY(reg) \
    (((reg) >> 0) & ((1U << 1) - 1))

/** @brief Set READY field in TRANSPORT_STATUS register */
#define REGMAP_FPGA_TRANSPORT_STATUS_SET_READY(reg, val) \
    (((reg) & ~(((1U << 1) - 1) << 0)) | (((val) & ((1U << 1) - 1)) << 0))

/** @brief Get PAGE_TAG field from TRANSPORT_STATUS register - Upper status byte. The acquisition-results layout is identified by 0xD4. */
#define REGMAP_FPGA_TRANSPORT_STATUS_GET_PAGE_TAG(reg) \
    (((reg) >> 24) & ((1U << 8) - 1))

/** @brief Set PAGE_TAG field in TRANSPORT_STATUS register */
#define REGMAP_FPGA_TRANSPORT_STATUS_SET_PAGE_TAG(reg, val) \
    (((reg) & ~(((1U << 8) - 1) << 24)) | (((val) & ((1U << 8) - 1)) << 24))


/* ============================================================================
 * Register Structures
 * ========================================================================== */

/**
 * @brief CMD Register (0x0)
 * Command Register
 * Access: RW
 */
struct __attribute__((aligned(REG_FIELD_SIZE))) regmap_fpga_cmd {
    reg_field_t cmd : 8; /**< Command byte controlling acquisition and helper functions. [0:7] */
};
static_assert(sizeof(struct regmap_fpga_cmd) == REG_FIELD_SIZE, "regmap_fpga_cmd size mismatch");


/**
 * @brief PLL_CONFIG_REG Register (0x1)
 * PLL Configuration Register
 * Access: RW
 */
struct __attribute__((aligned(REG_FIELD_SIZE))) regmap_fpga_pll_config_reg {
    reg_field_t tx_mux : 1; /**< TX Beamforming clock: 0 = 20 MHz, 1 = 100 MHz. [0:0] */
    reg_field_t afe_mux : 1; /**< AFE clock: 0 = 20 MHz (10 MHz sampling), 1 = 60 MHz (30 MHz sampling). [1:1] */
    reg_field_t _reserved0 : 1; /**< Reserved bits [2:2] */
    reg_field_t tx_ctrl : 1; /**< Multiplexer for PLL GL0 enable signal: 0 = Controlled by TX_EN, 1 = Defined by tx_clk_buf_en_wave_gen [3:3] */
    reg_field_t tx_en : 1; /**< PLL GL0 enable signal (active high) for TX clock output. [4:4] */
    reg_field_t afe_ctrl : 1; /**< Multiplexer for PLL GL1 enable signal: 0 = Controlled by AFE_EN, 1 = Defined by afe_clk_buf_en_wave_gen [5:5] */
    reg_field_t afe_en : 1; /**< PLL GL1 enable signal (active high) for AFE clock output. [6:6] */
    reg_field_t prm : 1; /**< SPI SS alt-func mux: drives either PLL async reset or power-down. [7:7] */
};
static_assert(sizeof(struct regmap_fpga_pll_config_reg) == REG_FIELD_SIZE, "regmap_fpga_pll_config_reg size mismatch");


/**
 * @brief LVDS_CH_EN Register (0x2)
 * LVDS Channel Enable
 * Access: RW
 */
struct __attribute__((aligned(REG_FIELD_SIZE))) regmap_fpga_lvds_ch_en {
    reg_field_t lvds_ch_en : 16; /**< Enable mask for 16 LVDS receivers; also gates which FIFOs accept writes and are later readable via SPI. If all 0, bit/frame clock buffers auto-disable. [0:15] */
    reg_field_t fifo_rd_wr_cnt : 12; /**< Samples per channel to write to and read from FIFOs. [16:27] */
    reg_field_t _reserved0 : 2; /**< Reserved bits [28:29] */
    reg_field_t clk_ctl_tx : 1; /**< TX chip clock buffer {0=WF gen control, 1=force ON} [30:30] */
    reg_field_t clk_ctl_afe : 1; /**< AFE clock buffer {0=WF gen control, 1=force ON}. [31:31] */
};
static_assert(sizeof(struct regmap_fpga_lvds_ch_en) == REG_FIELD_SIZE, "regmap_fpga_lvds_ch_en size mismatch");


/**
 * @brief WAVEFORM_GEN_REG_1 Register (0x3)
 * Waveform Generator Reg 1
 * Access: RW
 */
struct __attribute__((aligned(REG_FIELD_SIZE))) regmap_fpga_waveform_gen_reg_1 {
    reg_field_t tr_sw_sleep_time : 8; /**< TX switch (TR) sleep time after sync event. [0:7] */
    reg_field_t tr_sw_wkp_time : 8; /**< TX switch (TR) wake-up time before sync event. [8:15] */
    reg_field_t sync_period : 16; /**< Synchronization period of the waveform generator (defines PRF). [16:31] */
};
static_assert(sizeof(struct regmap_fpga_waveform_gen_reg_1) == REG_FIELD_SIZE, "regmap_fpga_waveform_gen_reg_1 size mismatch");


/**
 * @brief WAVEFORM_GEN_REG_2 Register (0x4)
 * Waveform Generator Reg 2
 * Access: RW
 */
struct __attribute__((aligned(REG_FIELD_SIZE))) regmap_fpga_waveform_gen_reg_2 {
    reg_field_t afe_clk_on_time : 16; /**< Duration the AFE clock stays on around sync. [0:15] */
    reg_field_t afe_wkp_time : 8; /**< AFE wake-up lead time before sync. [16:23] */
};
static_assert(sizeof(struct regmap_fpga_waveform_gen_reg_2) == REG_FIELD_SIZE, "regmap_fpga_waveform_gen_reg_2 size mismatch");


/**
 * @brief WAVEFORM_GEN_REG_3 Register (0x5)
 * Waveform Generator Reg 3
 * Access: RW
 */
struct __attribute__((aligned(REG_FIELD_SIZE))) regmap_fpga_waveform_gen_reg_3 {
    reg_field_t afe_data_acq_time : 16; /**< Duration of AFE data acquisition window. [0:15] */
    reg_field_t capture_delay : 16; /**< Delay from TX sync to start of AFE acquisition. [16:31] */
};
static_assert(sizeof(struct regmap_fpga_waveform_gen_reg_3) == REG_FIELD_SIZE, "regmap_fpga_waveform_gen_reg_3 size mismatch");


/**
 * @brief TGC_REG_1 Register (0x6)
 * TGC Register 1
 * Access: RW
 */
struct __attribute__((aligned(REG_FIELD_SIZE))) regmap_fpga_tgc_reg_1 {
    reg_field_t tgc_clk_divider : 32; /**< Clock divider for TGC slope generation (gain ramp rate). [0:31] */
};
static_assert(sizeof(struct regmap_fpga_tgc_reg_1) == REG_FIELD_SIZE, "regmap_fpga_tgc_reg_1 size mismatch");


/**
 * @brief TGC_REG_2 Register (0x7)
 * TGC Register 2
 * Access: RW
 */
struct __attribute__((aligned(REG_FIELD_SIZE))) regmap_fpga_tgc_reg_2 {
    reg_field_t tgc_capture_time : 32; /**< Duration the TGC gain adjustment is applied after start. [0:31] */
};
static_assert(sizeof(struct regmap_fpga_tgc_reg_2) == REG_FIELD_SIZE, "regmap_fpga_tgc_reg_2 size mismatch");


/**
 * @brief TGC_REG_3 Register (0x8)
 * TGC Register 3
 * Access: RW
 */
struct __attribute__((aligned(REG_FIELD_SIZE))) regmap_fpga_tgc_reg_3 {
    reg_field_t tgc_delay_finish : 32; /**< Extra delay before TGC returns to default after final gain. [0:31] */
};
static_assert(sizeof(struct regmap_fpga_tgc_reg_3) == REG_FIELD_SIZE, "regmap_fpga_tgc_reg_3 size mismatch");


/**
 * @brief TGC_REG_4 Register (0x9)
 * TGC Register 4
 * Access: RW
 */
struct __attribute__((aligned(REG_FIELD_SIZE))) regmap_fpga_tgc_reg_4 {
    reg_field_t tgc_delay_start : 32; /**< Delay before TGC gain ramp begins after trigger. [0:31] */
};
static_assert(sizeof(struct regmap_fpga_tgc_reg_4) == REG_FIELD_SIZE, "regmap_fpga_tgc_reg_4 size mismatch");


/**
 * @brief AFE_TX_RST_REG Register (0xA)
 * AFE and TX Reset Register
 * Access: RW
 */
struct __attribute__((aligned(REG_FIELD_SIZE))) regmap_fpga_afe_tx_rst_reg {
    reg_field_t afe : 1; /**< Reset AFE. [0:0] */
    reg_field_t tx : 1; /**< Reset TX. [1:1] */
    reg_field_t afe_fpwd_src : 1; /**< AFE fast power-down control source. Enables control from AFE_FPWD_CTRL if set. [2:2] */
    reg_field_t afe_fpwd_ctrl : 1; /**< Drive AFE fast power-down when set. [3:3] */
    reg_field_t afe_gpwd_src : 1; /**< AFE global power-down control source. Enables control from AFE_GPWD_CTRL if set. [4:4] */
    reg_field_t afe_gpwd_ctrl : 1; /**< Drive AFE global power-down when set. [5:5] */
    reg_field_t tx_en_src : 1; /**< TX enable control source. Enables control from TX_EN_CTRL if set. [6:6] */
    reg_field_t tx_en_ctrl : 1; /**< Drive TX_EN when set. [7:7] */
};
static_assert(sizeof(struct regmap_fpga_afe_tx_rst_reg) == REG_FIELD_SIZE, "regmap_fpga_afe_tx_rst_reg size mismatch");


/**
 * @brief WAVEFORM_GEN_REG_4 Register (0xB)
 * Waveform Generator Reg 4
 * Access: RW
 */
struct __attribute__((aligned(REG_FIELD_SIZE))) regmap_fpga_waveform_gen_reg_4 {
    reg_field_t n_shots_to_make : 8; /**< Number of shots to average into one frame. Zero selects one shot. [0:7] */
    reg_field_t _reserved0 : 8; /**< Reserved bits [8:15] */
    reg_field_t start_capture_time : 16; /**< Preload of main counter to set deterministic delay from trigger to first TX event. [16:31] */
};
static_assert(sizeof(struct regmap_fpga_waveform_gen_reg_4) == REG_FIELD_SIZE, "regmap_fpga_waveform_gen_reg_4 size mismatch");


/**
 * @brief WAVEFORM_GEN_REG_5 Register (0xC)
 * Waveform Generator Reg 5
 * Access: RW
 */
struct __attribute__((aligned(REG_FIELD_SIZE))) regmap_fpga_waveform_gen_reg_5 {
    reg_field_t refresh_cnt_period : 16; /**< Period of refresh counter for periodic TR_EN pulses (TX LDO refresh). [0:15] */
    reg_field_t tr_en_on_time : 8; /**< High-time of TR_EN during each refresh cycle. [16:23] */
    reg_field_t _reserved0 : 1; /**< Reserved bits [24:24] */
    reg_field_t external_acquisition : 1; /**< Arm with the start command and capture on external rising edges. [25:25] */
    reg_field_t _reserved1 : 5; /**< Reserved bits [26:30] */
    reg_field_t fen : 1; /**< Enable periodic refresh mechanism. [31:31] */
};
static_assert(sizeof(struct regmap_fpga_waveform_gen_reg_5) == REG_FIELD_SIZE, "regmap_fpga_waveform_gen_reg_5 size mismatch");


/**
 * @brief EXT_INT_TRIG_REG Register (0xD)
 * External/Internal Trigger Register
 * Access: RW
 */
struct __attribute__((aligned(REG_FIELD_SIZE))) regmap_fpga_ext_int_trig_reg {
    reg_field_t eit : 1; /**< Select trigger source. [0:0] */
    reg_field_t mim : 2; /**< MCU interrupt source select (SPI mux must not be 00). [1:2] */
    reg_field_t otm : 2; /**< Output trigger (trigger_o) source select. [3:4] */
    reg_field_t _reserved0 : 18; /**< Reserved bits [5:22] */
    reg_field_t status_control : 9; /**< Transport diagnostic controls in bits 31:23. The stream and acquisition-results settings clear the other diagnostic controls. [23:31] */
};
static_assert(sizeof(struct regmap_fpga_ext_int_trig_reg) == REG_FIELD_SIZE, "regmap_fpga_ext_int_trig_reg size mismatch");


/**
 * @brief RESERVED_REG Register (0xE)
 * Reserved address. Leave unchanged.
 * Access: RO
 */
struct __attribute__((aligned(REG_FIELD_SIZE))) regmap_fpga_reserved_reg {
    reg_field_t reserved : 32; /**< [0:31] */
};
static_assert(sizeof(struct regmap_fpga_reserved_reg) == REG_FIELD_SIZE, "regmap_fpga_reserved_reg size mismatch");


/**
 * @brief TRANSPORT_STATUS Register (0xF)
 * Read-only SPI status. EXT_INT_TRIG_REG.STATUS_CONTROL selects the layout.
 * Access: RO
 */
struct __attribute__((aligned(REG_FIELD_SIZE))) regmap_fpga_transport_status {
    reg_field_t ready : 1; /**< Stream data ready on the STREAM page, or acquisition results ready on the RESULTS page. [0:0] */
    reg_field_t _reserved0 : 23; /**< Reserved bits [1:23] */
    reg_field_t page_tag : 8; /**< Upper status byte. The acquisition-results layout is identified by 0xD4. [24:31] */
};
static_assert(sizeof(struct regmap_fpga_transport_status) == REG_FIELD_SIZE, "regmap_fpga_transport_status size mismatch");


