/* ============================================================================
 * Register Map Implementation Struct
 * ========================================================================== */

/** @brief Complete register map structure for Regmap_FPGA */
typedef struct regmap_fpga {
    union regmap_fpga_cmd_u cmd; /**< Command Register */
    union regmap_fpga_pll_config_reg_u pll_config_reg; /**< PLL Configuration Register */
    union regmap_fpga_lvds_ch_en_u lvds_ch_en; /**< LVDS Channel Enable */
    union regmap_fpga_waveform_gen_reg_1_u waveform_gen_reg_1; /**< Waveform Generator Reg 1 */
    union regmap_fpga_waveform_gen_reg_2_u waveform_gen_reg_2; /**< Waveform Generator Reg 2 */
    union regmap_fpga_waveform_gen_reg_3_u waveform_gen_reg_3; /**< Waveform Generator Reg 3 */
    union regmap_fpga_tgc_reg_1_u tgc_reg_1; /**< TGC Register 1 */
    union regmap_fpga_tgc_reg_2_u tgc_reg_2; /**< TGC Register 2 */
    union regmap_fpga_tgc_reg_3_u tgc_reg_3; /**< TGC Register 3 */
    union regmap_fpga_tgc_reg_4_u tgc_reg_4; /**< TGC Register 4 */
    union regmap_fpga_afe_tx_rst_reg_u afe_tx_rst_reg; /**< AFE and TX Reset Register */
    union regmap_fpga_waveform_gen_reg_4_u waveform_gen_reg_4; /**< Waveform Generator Reg 4 */
    union regmap_fpga_waveform_gen_reg_5_u waveform_gen_reg_5; /**< Waveform Generator Reg 5 */
    union regmap_fpga_ext_int_trig_reg_u ext_int_trig_reg; /**< External/Internal Trigger Register */
    union regmap_fpga_reserved_reg_u reserved_reg; /**< Reserved address. Leave unchanged. */
    union regmap_fpga_transport_status_u transport_status; /**< Read-only SPI status. EXT_INT_TRIG_REG.STATUS_CONTROL selects the layout. */
} regmap_fpga_t;

/* ============================================================================
 * Default Initialization Macro
 * ========================================================================== */

/** @brief Initialize register map with reset values */
#define REGMAP_FPGA_INIT (regmap_fpga_t){ \
    .cmd.raw = REGMAP_FPGA_CMD_RESET,  \
    .pll_config_reg.raw = REGMAP_FPGA_PLL_CONFIG_REG_RESET,  \
    .lvds_ch_en.raw = REGMAP_FPGA_LVDS_CH_EN_RESET,  \
    .waveform_gen_reg_1.raw = REGMAP_FPGA_WAVEFORM_GEN_REG_1_RESET,  \
    .waveform_gen_reg_2.raw = REGMAP_FPGA_WAVEFORM_GEN_REG_2_RESET,  \
    .waveform_gen_reg_3.raw = REGMAP_FPGA_WAVEFORM_GEN_REG_3_RESET,  \
    .tgc_reg_1.raw = REGMAP_FPGA_TGC_REG_1_RESET,  \
    .tgc_reg_2.raw = REGMAP_FPGA_TGC_REG_2_RESET,  \
    .tgc_reg_3.raw = REGMAP_FPGA_TGC_REG_3_RESET,  \
    .tgc_reg_4.raw = REGMAP_FPGA_TGC_REG_4_RESET,  \
    .afe_tx_rst_reg.raw = REGMAP_FPGA_AFE_TX_RST_REG_RESET,  \
    .waveform_gen_reg_4.raw = REGMAP_FPGA_WAVEFORM_GEN_REG_4_RESET,  \
    .waveform_gen_reg_5.raw = REGMAP_FPGA_WAVEFORM_GEN_REG_5_RESET,  \
    .ext_int_trig_reg.raw = REGMAP_FPGA_EXT_INT_TRIG_REG_RESET,  \
    .reserved_reg.raw = REGMAP_FPGA_RESERVED_REG_RESET,  \
    .transport_status.raw = REGMAP_FPGA_TRANSPORT_STATUS_RESET \
}

#endif /* REGMAP_FPGA_H */